-- Demo workspace for the "Geiger Notes" project (ebcc7910-1a0e-4e91-8c3b-752f3c4292d3).
-- Generated from lib/forms/templates.js; deterministic ids, timestamps relative to now(). Re-running restores the demo and refreshes its dates. Never ledgered.
-- 11 forms, 504 responses, 2615 funnel events, 21 partials, 27 versions, 8 comments, 25 activity rows.

do $guard$ begin
  if not exists (select 1 from public.projects where id = 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3') then
    raise exception 'Project ebcc7910-1a0e-4e91-8c3b-752f3c4292d3 does not exist';
  end if;
end $guard$;

-- Forms
on conflict (id) do update set project_id = excluded.project_id, slug = excluded.slug, title = excluded.title, description = excluded.description, status = excluded.status, category = excluded.category, tags = excluded.tags, schema = excluded.schema, settings = excluded.settings, is_template = excluded.is_template, created_at = excluded.created_at, updated_at = excluded.updated_at, published_at = excluded.published_at, deleted_at = null;

-- Responses (inserts bump forms.response_count via forms.sync_response_count)
on conflict (id) do update set answers = excluded.answers, respondent_name = excluded.respondent_name, respondent_email = excluded.respondent_email, status = excluded.status, priority = excluded.priority, score = excluded.score, submitted_at = excluded.submitted_at, updated_at = excluded.updated_at, completion_ms = excluded.completion_ms, tags = excluded.tags, assignee = excluded.assignee, approval = excluded.approval, payment_status = excluded.payment_status, payment_amount = excluded.payment_amount, payment_currency = excluded.payment_currency, payment_ref = excluded.payment_ref, deleted_at = null;
on conflict (id) do update set answers = excluded.answers, respondent_name = excluded.respondent_name, respondent_email = excluded.respondent_email, status = excluded.status, priority = excluded.priority, score = excluded.score, submitted_at = excluded.submitted_at, updated_at = excluded.updated_at, completion_ms = excluded.completion_ms, tags = excluded.tags, assignee = excluded.assignee, approval = excluded.approval, payment_status = excluded.payment_status, payment_amount = excluded.payment_amount, payment_currency = excluded.payment_currency, payment_ref = excluded.payment_ref, deleted_at = null;
on conflict (id) do update set answers = excluded.answers, respondent_name = excluded.respondent_name, respondent_email = excluded.respondent_email, status = excluded.status, priority = excluded.priority, score = excluded.score, submitted_at = excluded.submitted_at, updated_at = excluded.updated_at, completion_ms = excluded.completion_ms, tags = excluded.tags, assignee = excluded.assignee, approval = excluded.approval, payment_status = excluded.payment_status, payment_amount = excluded.payment_amount, payment_currency = excluded.payment_currency, payment_ref = excluded.payment_ref, deleted_at = null;

-- Funnel events (view → start → submit)
on conflict (id) do update set created_at = excluded.created_at;
on conflict (id) do update set created_at = excluded.created_at;
on conflict (id) do update set created_at = excluded.created_at;
on conflict (id) do update set created_at = excluded.created_at;
on conflict (id) do update set created_at = excluded.created_at;
on conflict (id) do update set created_at = excluded.created_at;

-- Abandoned partial submissions
on conflict (id) do update set answers = excluded.answers, progress = excluded.progress, created_at = excluded.created_at, updated_at = excluded.updated_at, completed_at = null, deleted_at = null;

-- Version history
on conflict (form_id, version) do update set label = excluded.label, author = excluded.author, schema = excluded.schema, settings = excluded.settings, created_at = excluded.created_at;

-- Internal comments
on conflict (id) do update set author = excluded.author, body = excluded.body, created_at = excluded.created_at;

-- Workspace activity
on conflict (id) do update set actor_name = excluded.actor_name, action = excluded.action, detail = excluded.detail, created_at = excluded.created_at;

